      {
        "type": "sectionTitle",
        "text": "1.8 Las fuentes de información disponibles hasta el momento."
      },
      {
        "type": "paragraph",
        "text": "Con respecto a la información matemática disponible dice: «Las fuentes más antiguas son las tablillas cocidas de los babilonios y los papiros de Egipto.» (Saenz Quiroga, 2005)"
      },
      {
        "type": "paragraph",
        "text": "Se dice acerca de las fuentes matemáticas: «Las fuentes matemáticas en Babilonia se derivan de más de 400 tablillas de arcilla desveladas desde 1850. Labradas en escritura cuneiforme, fueron grabadas mientras la arcilla estaba húmeda y cocida posteriormente en un horno o secadas al sol. Algunas de ellas parecen ser tareas graduadas. Las primeras evidencias matemáticas escritas se remontan a los antiguos sumerios, en Mesopotamia, quienes desarrollaron un sistema de metrología desde el año 3,000 a.c. Alrededor del 2500 a.c. en adelante, los sumerios escribieron tablas de multiplicar en tablillas de arcilla, trataron ejercicios geométricos y problemas de división. Las señales más tempranas de los numerales babilónicos también datan de ese periodo."
      },
      {
        "type": "paragraph",
        "text": "Las tabletas de arcilla recuperadas datan del 1800 al 1600 a.e.c., e incluyen fracciones, álgebra, ecuaciones cuadráticas y cubicas, y el cálculo de primos gemelos regulares recíprocos, incluyen tablas de multiplicar y métodos para resolver ecuaciones lineales y cuadráticas. La tablilla babilónica YBC 7289 da una aproximación de √2 con cinco decimales. Las matemáticas babilónicas se escribieron usando un sistema de numeración sexagesimal (base 60). Por eso la división de un minuto en 60 segundos, la hora en 60 minutos, el círculo en 360 (60 × 6) grados y las subdivisiones sexagesimales de esta unidad de medida de ángulos en minutos y segundos."
      },
      {
        "type": "paragraph",
        "text": "Los avances en matemáticas fueron facilitados por el hecho de que el número 60 tiene muchos divisores»."
      }
