        "text": "Para este apartado es necesario definir que es un \"gnomon\". Del cual se dice lo siguiente: «El libro segundo comienzo con las definiciones de rectángulo y de \"gnomon\", que es una especie de L obtenida al quitarle a un rectángulo otro semejante más pequeño en un vértice. (Navarro Loidi, 2002)"
