        "text": "I. Cuadrado de una suma y una diferencia. • (𝒂+𝒃)𝟐 = 𝒂𝟐 +𝟐𝒂𝒃+𝒃𝟐 • (𝒂−𝒃)𝟐 = 𝒂𝟐 −𝟐𝒂𝒃+𝒃𝟐 En general: (𝒂±𝒃)𝟐 = 𝒂𝟐 ±𝟐𝒂𝒃+𝒃𝟐 II. Producto de una suma y una diferencia. Es igual a la diferencia de cuadrados (𝒂+𝒃)(𝒂−𝒃) = 𝒂𝟐 −𝒃𝟐 III. Cuadrado de un Trinomio. (𝒂+𝒃+𝒄)𝟐 = 𝒂𝟐 +𝒃𝟐 +𝒄𝟐 +𝟐𝒂𝒃+𝟐𝐚𝐜+𝟐𝐛𝐜 IV. Cubo de una suma o diferencia (𝒂+𝒃)𝟑 = 𝒂𝟑 +𝟑𝒂𝟐𝒃+𝟑𝒂𝒃𝟐 +𝒃𝟑 (𝒂−𝒃)𝟑 = 𝒂𝟑 −𝟑𝒂𝟐𝒃+𝟑𝒂𝒃𝟐 −𝒃𝟑 En general: (𝒂±𝒃)𝟑 = 𝒂𝟑 ±𝟑𝒂𝟐𝒃+𝟑𝒂𝒃𝟐 ±𝒃𝟑 V. Producto de dos binomios que tienen un término común. (𝒙+𝒂)(𝒙+𝒃) = 𝒙𝟐 +(𝒂+𝒃)𝒙+𝒂𝒃 VI. Producto de un binomio por un trinomio que da una suma o diferencia de cubos. (𝒂+𝒃)(𝒂𝟐−𝒂𝒃+𝒃𝟐) = 𝒂𝟑 +𝒃𝟑 (𝒂−𝒃)(𝒂𝟐 +𝒂𝒃+𝒃𝟐) = 𝒂𝟑 −𝒃𝟑 De manera general: (𝒂±𝒃)(𝒂𝟐 ∓𝒂𝒃+𝒃𝟐) = 𝒂𝟑 ±𝒃𝟑 VII. Identidades de Legendre: (𝒂+𝒃)𝟐 +(𝒂−𝒃)𝟐 = 𝟐(𝒂𝟐 +𝒃𝟐) (𝒂+𝒃)𝟐 −(𝒂−𝒃)𝟐 = 𝟒𝒂𝒃 VIII. Identidades de Lagrange: (𝒂𝒙+𝒃𝒚)𝟐+(𝒃𝒙−𝒂𝒚)𝟐 = (𝒙𝟐 +𝒚𝟐)(𝒂𝟐 +𝒃𝟐) (𝒂𝒙+𝒃𝒚+𝒄𝒛)+(𝒃𝒙−𝒂𝒚)𝟐 +(𝒄𝒙−𝒂𝒛)𝟐 +(𝒄𝒚−𝒃𝒛)𝟐 = (𝒂𝟐 +𝒃𝟐 +𝒄𝟐)(𝒙𝟐 +𝒚𝟐 +𝒛𝟐)"
