        "text": "(𝒂+𝒃)(𝒂 𝟐 −𝒂𝒃+𝒃𝟐) = 𝒂𝟑 +𝒃𝟑 (𝒂+𝒃)(𝒂 𝟒 −𝒂𝟑𝒃+𝒂𝟐𝒃𝟐 −𝒂𝒃𝟑 +𝒃𝟒) = 𝒂𝟓 +𝒃𝟓 (𝒂+𝒃)(𝒂𝟔 −𝒂𝟓𝒃+𝒂𝟒𝒃𝟐 −𝒂𝟑𝒃𝟑 +𝒂𝟐𝒃𝟒 −𝒂𝒃𝟓 +𝒃𝟔) = 𝒂𝟕 +𝒃𝟕, etc."
