        "type": "paragraph",
        "text": "Dear Sir/Madam: Granting attention to your experience in mathematics (algebra, geometric algebra, theory of numbers, etc.), you are hereby being requested to respond to a question whose answer will be of much use for a research being done since August, 2011, geared towards improving the teaching of mathematics in Nicaragua, Central America. (Thanks for your kind collaboration). Please reply to Bienvenido Hernaldo Acevedo González, bienvenidohernaldoa@gmail.com or bienv1@yahoo.com"
