        "type": "paragraph",
        "text": "Factorizemos con: 𝒂𝟐 + 𝒃𝟐 = 𝒄𝟐 = ( 𝒄𝟐+𝒂.𝒄 ) ( 𝒄𝟐−𝒂.𝒄 ) 𝒃 𝒃"
